using UnityEngine;
using UnityEngine.Events;
using UnityEngine.SceneManagement;

// Holds the score and game state. Exactly one per scene.
public class GameManager : MonoBehaviour
{
    public static GameManager Instance { get; private set; }

    public UnityEvent<int> onScoreChanged;
    public UnityEvent onGameOver;

    public int Score { get; private set; }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
    }

    public void AddScore(int amount)
    {
        Score += amount;
        onScoreChanged?.Invoke(Score);
    }

    public void GameOver()
    {
        onGameOver?.Invoke();
        Invoke(nameof(Restart), 2f);
    }

    public void Restart()
    {
        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
    }
}

using UnityEngine;
using Unity.Cinemachine;

// Triggers a camera shake, e.g. from Health.onHealthChanged.
[RequireComponent(typeof(CinemachineImpulseSource))]
public class ShakeOnHit : MonoBehaviour
{
    [SerializeField] private float force = 1f;
    private CinemachineImpulseSource source;

    private void Awake()
    {
        source = GetComponent<CinemachineImpulseSource>();
    }

    public void Shake()
    {
        source.GenerateImpulseWithForce(force);
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;

// For the buttons in the main menu.
public class MenuActions : MonoBehaviour
{
    [SerializeField] private string gameScene = "Game";

    public void Play()
    {
        Time.timeScale = 1f;
        SceneManager.LoadScene(gameScene);
    }

    public void Quit()
    {
        Application.Quit();
#if UNITY_EDITOR
        UnityEditor.EditorApplication.isPlaying = false;
#endif
    }
}
